#include "search.h"
#include <cassert>
using namespace v2;
int main(){init();Learner m;m.load("dist/models/ntuple-v3.bin");Board b{13,0,0,0,12,0,0,0,1,2,3,4,0,0,0,0};double initial=m.value(b,2);m.enableFive();assert(m.value(b,2)==initial);auto before=m.base.w;m.update(b,initial+100,.1);assert(m.base.w==before);assert(std::abs(m.value(b,2)-initial-10)<1e-5);double original=m.value(b,2);for(int sym=0;sym<8;sym++){Board transformed{};for(int pos=0;pos<16;pos++){int y=pos/4,x=pos%4;if(sym>=4)x=3-x;for(int k=0;k<sym%4;k++){int ny=x;x=3-y;y=ny;}transformed[y*4+x]=b[pos];}assert(std::abs(m.value(transformed,2)-original)<1e-6);}m.save("/tmp/threes-v4-model-check");Learner loaded;loaded.load("/tmp/threes-v4-model-check.ntd","/tmp/threes-v4-model-check.five");assert(loaded.value(b,2)==m.value(b,2));Learner tc;tc.load("dist/models/ntuple-v3.bin");tc.enableTC();auto ids=tc.base.indices(b);tc.update(b,tc.value(b,2)+100,.1);tc.update(b,tc.value(b,2)-100,.1);for(int id:ids){assert(std::abs(tc.errors[id])<1e-8);assert(tc.absolute[id]>0);}auto weights=tc.base.w;tc.update(b,tc.value(b,2)+100,.1);assert(tc.base.w==weights);std::cout<<"zero-residual identity, normalized update, frozen base, D4 symmetry, roundtrip and TC cancellation pass\n";}
